/** Display-only copy. Never use translations as identifiers or request values. */
export const languages = [
  { code: 'en', label: 'English', htmlLang: 'en' },
  { code: 'ur-Latn', label: 'Roman Urdu', htmlLang: 'ur-Latn' },
  { code: 'vi', label: 'Tiếng Việt', htmlLang: 'vi' },
] as const;
export type Language = typeof languages[number]['code'];
export const languagePreferenceKey = 'sasify-language';
export function isLanguage(value: unknown): value is Language {
  return languages.some(language => language.code === value);
}
export function isPublicPath(path: string) {
  return !/^\/(?:orders-admin|team)(?:\/|$)/.test(path);
}

