export const translations = Object.fromEntries(copy.map(([english, ur, vi]) => [english, { 'ur-Latn': ur, vi }])) as Record<string, Record<Exclude<Language, 'en'>, string>>;
const normalize = (value: string) => value.replace(/\s+/g, ' ').trim();
const caseInsensitiveCopy = new Map(Object.entries(translations).map(([key, pair]) => [key.toLowerCase(), pair]));

export function translateText(value: string, language: Language): string {
  if (language === 'en' || !value.trim()) return value;
  const normalized = normalize(value);
  const direct = (translations[normalized] || caseInsensitiveCopy.get(normalized.toLowerCase()))?.[language];
  if (direct) return value.replace(value.trim(), direct);
  // Presentation-only number patterns; preserve the exact original numbers.
  const patterns: Array<[RegExp, string, string]> = [
    [/^Compare all (.+) plans and prices$/, '$1 ke tamam plans aur prices compare karain', 'So sánh tất cả các gói và giá $1'],
    [/^(\d+) products$/, '$1 products', '$1 sản phẩm'],
    [/^(\d+) products in catalog$/, 'Catalog mein $1 products', '$1 sản phẩm trong danh mục'],
    [/^(\d+) products? found$/, '$1 products milay', 'Tìm thấy $1 sản phẩm'],
    [/^(\d+) available$/, '$1 available', 'Có sẵn $1'],
    [/^(\d+) in stock$/, '$1 available', 'Còn $1'],
    [/^(\d+) (?:Month|Months)$/, '$1 mahinay', '$1 tháng'],
    [/^(\d+) (?:Day|Days)$/, '$1 din', '$1 ngày'],
    [/^(\d+) (?:Year|Years)$/, '$1 saal', '$1 năm'],
    [/^Full (\d+)-day warranty$/, 'Poore $1 din ki warranty', 'Bảo hành đầy đủ $1 ngày'],
    [/^Last updated: (.+)$/, 'Aakhri update: $1', 'Cập nhật lần cuối: $1'],
    [/^Show prices in (PKR|USD)$/, 'Prices $1 mein dikhayen', 'Hiển thị giá bằng $1'],
    [/^Balance: PKR ([\d,]+) · 5% discount on eligible products$/, 'Balance: PKR $1 · eligible products par 5% discount', 'Số dư: PKR $1 · giảm 5% cho sản phẩm đủ điều kiện'],
    [/^Search (ChatGPT(?: Plus)?)$/, '$1 dhoondain', 'Tìm $1'],
    [/^Welcome back, (.+)$/, 'Dobara khush aamdeed, $1', 'Chào mừng trở lại, $1'],
    [/^Resend (\d+)s$/, '$1s mein dobara bhejain', 'Gửi lại sau $1 giây'],
  ];
  for (const [pattern, ur, vi] of patterns) if (pattern.test(normalized)) {
    return value.replace(value.trim(), normalized.replace(pattern, language === 'vi' ? vi : ur));
  }
  return value;
}
